local function add(ctx,self,a,h)local p=ctx:controller(self);ctx:grant_player_keyword(p,"cthun_buffs");ctx:increment_player_data(p,"cthun_attack_buff",a);ctx:increment_player_data(p,"cthun_health_buff",h)end
return {api_version=1,id="OG_282",name="Blade of C'Thun",text="<b>Battlecry:</b> Destroy a minion. Add its Attack and Health to your C'Thun's <i>(wherever it is).</i>",set="OG",type="minion",class="rogue",rarity="epic",cost=7,attack=4,health=4,keywords={"battlecry"},target_mode="required_if_available",targets=function(ctx)return ctx:minions()end,on_battlecry=function(ctx,self,target)if target then local e=ctx:entity(target);ctx:destroy(target);add(ctx,self,e.attack,e.health)end end}
